def calculer():
    nom = entree_nom.get().strip()
    try:
        taille = float(entree_taille.get().replace(",", "."))
        poids = float(entree_poids.get().replace(",", "."))
        if taille <= 0 or poids <= 0:
            raise ValueError
    except ValueError:
        messagebox.showerror("Erreur", "Entre un nom, une taille valide en mètres et un poids valide en kg.")
        return

    imc = poids / (taille ** 2)
    if imc <= 18.5:
        categorie = "Maigreur"
    elif imc <= 25:
        categorie = "Normal"
    elif imc <= 30:
        categorie = "Surpoids"
    elif imc <= 40:
        categorie = "Obésité modérée"
    else:
        categorie = "Obésité sévère"

    messagebox.showinfo(
        "Résultat IMC",
        f"Bonjour {nom} !\\n\\nVotre IMC est : {imc:.2f}\\nCatégorie : {categorie}"
    )

fenetre = tk.Tk()
fenetre.title("Calcul de l'IMC")
fenetre.geometry("540x690")
fenetre.resizable(False, False)

tk.Label(fenetre, text="Calculateur IMC", font=("Arial", 18, "bold")).pack(pady=(10, 6))

# Tkinter affiche directement le GIF intégré.
photo = tk.PhotoImage(data=IMAGE_DATA)
tk.Label(fenetre, image=photo).pack(pady=4)

formulaire = tk.Frame(fenetre)
formulaire.pack(pady=12)

tk.Label(formulaire, text="Votre nom :").grid(row=0, column=0, sticky="e", padx=8, pady=7)
entree_nom = tk.Entry(formulaire, width=25)
entree_nom.grid(row=0, column=1, padx=8, pady=7)

tk.Label(formulaire, text="Taille (m) :").grid(row=1, column=0, sticky="e", padx=8, pady=7)
entree_taille = tk.Entry(formulaire, width=25)
entree_taille.grid(row=1, column=1, padx=8, pady=7)

tk.Label(formulaire, text="Poids (kg) :").grid(row=2, column=0, sticky="e", padx=8, pady=7)
entree_poids = tk.Entry(formulaire, width=25)
entree_poids.grid(row=2, column=1, padx=8, pady=7)

tk.Button(
    fenetre,
    text="Calculer mon IMC",
    command=calculer,
    font=("Arial", 12, "bold"),
    padx=14,
    pady=7
).pack(pady=10)

fenetre.mainloop()
